Parameters::Parameters(Type m11, Type m12, Type m21, Type m22)
    : Parameters(2)
{
    data(0, 0) = m11;
    data(0, 1) = m12;
    data(1, 0) = m21;
    data(1, 1) = m22;
}

Parameters::Parameters(int num_ports)
{
